-- Mexicano opening rounds: how many rounds are mixed before the ladder starts.
--
-- After one random round the standing is mostly the luck of the draw — who you
-- were partnered with and against — and from round 2 the ladder locks that luck
-- in: whoever it placed low only meets the others it placed low. Opening rounds
-- are generated by Americano's rules instead (no repeated partner while a fresh
-- one exists, fresh opponents, spread across courts), so the standing has real
-- results behind it before it starts deciding who plays whom.
--
-- 1 is today's behaviour — a random round 1, the ladder from round 2 — so every
-- existing tournament keeps the schedule it was played under. Americano ignores
-- the column: every round of it is mixed.
--
-- Pairing is generated in the client (ADR-0003), so nothing here reads the
-- value beyond storing it; create_tournament has to accept it, or a tournament
-- created with three opening rounds silently falls back to one.

alter table public.tournaments
  add column opening_rounds int not null default 1
    check (opening_rounds >= 1);

comment on column public.tournaments.opening_rounds is
  'Mexicano only: rounds paired by Americano rules before the standing decides
   the pairings. 1 = a single random round, as before.';

create or replace function public.create_tournament(p_tournament jsonb)
returns table (id uuid, slug text)
language plpgsql
set search_path = public
as $$
declare
  v_id uuid;
  v_court_ids uuid[] := '{}';
  v_court text;
  v_court_id uuid;
  v_participant jsonb;
  v_index int;
  v_seed_index int;
begin
  insert into public.tournaments (
    owner_id, name, format, team_format, game_points, rest_points, pairing_formula,
    scoring, neutral_rounds, opening_rounds
  )
  values (
    (select auth.uid()),
    p_tournament ->> 'name',
    (p_tournament ->> 'format')::public.tournament_format,
    (p_tournament ->> 'team_format')::public.team_format,
    (p_tournament ->> 'game_points')::int,
    (p_tournament ->> 'rest_points')::int,
    nullif(p_tournament ->> 'pairing_formula', '')::public.pairing_formula,
    coalesce(nullif(p_tournament ->> 'scoring', ''), 'points'),
    coalesce((p_tournament ->> 'neutral_rounds')::int, 1),
    coalesce((p_tournament ->> 'opening_rounds')::int, 1)
  )
  returning tournaments.id into v_id;

  v_index := 0;
  for v_court in select jsonb_array_elements_text(coalesce(p_tournament -> 'courts', '[]'::jsonb))
  loop
    v_index := v_index + 1;
    insert into public.courts (tournament_id, name, position)
    values (v_id, v_court, v_index)
    returning courts.id into v_court_id;
    v_court_ids := v_court_ids || v_court_id;
  end loop;

  v_index := 0;
  for v_participant in
    select jsonb_array_elements(coalesce(p_tournament -> 'participants', '[]'::jsonb))
  loop
    v_index := v_index + 1;
    v_seed_index := (v_participant ->> 'seed_court_index')::int;

    insert into public.participants (
      tournament_id, name, entry_order, seed_court_id, seed_side
    )
    values (
      v_id,
      v_participant ->> 'name',
      v_index,
      case
        when v_seed_index is null then null
        -- jsonb indexes are 0-based, Postgres arrays are 1-based
        else v_court_ids[v_seed_index + 1]
      end,
      nullif(v_participant ->> 'seed_side', '')::public.match_side
    );
  end loop;

  return query
    select t.id, t.slug from public.tournaments t where t.id = v_id;
end;
$$;

revoke all on function public.create_tournament(jsonb) from public, anon;
grant execute on function public.create_tournament(jsonb) to authenticated;
